  const grd=g.createRadialGradient(16,16,0,16,16,16); grd.addColorStop(0,'rgba(255,255,255,1)'); grd.addColorStop(0.4,'rgba(255,255,255,0.7)'); grd.addColorStop(1,'rgba(255,255,255,0)');
