    const fallback=glossaryListenData(pick)||{placement:{title:(b.glyph||'')+' '+(b.label||b.id)+' (natal)',text:'Natal placement — a fixed reference in your chart, used as a symbolic study lens.'},personal:{available:false}};
    fillTempleStudy(pick, fallback, false);
